#!/usr/bin/env bash
# ZONO — apply קונים+מוכרים retrofit (server scope + compute + URL pagination).
# Realigns to origin/main, applies ONE commit, pushes. macOS-safe base64 decode.
set -euo pipefail
cd "$(dirname "$0")"
echo "→ repo: $(pwd)"
git am --abort 2>/dev/null || true
git fetch origin
git checkout main
git reset --hard origin/main
cat > /tmp/zono-bs.patch.b64 <<'B64EOF'

B64EOF
base64 -d < /tmp/zono-bs.patch.b64 > /tmp/zono-bs.patch
# 3-way keeps it robust if a hunk context shifted slightly.
git am --3way /tmp/zono-bs.patch
echo "→ commit applied:"; git log --oneline -2
git push origin main
echo "✓ pushed. Redeploy will pick up /buyers and /sellers."
